// And groups predicates with the AND operator between them.
func And(predicates ...predicate.AIGenerationJob) predicate.AIGenerationJob {
	return predicate.AIGenerationJob(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.AIGenerationJob) predicate.AIGenerationJob {
	return predicate.AIGenerationJob(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.AIGenerationJob) predicate.AIGenerationJob {
	return predicate.AIGenerationJob(sql.NotPredicates(p))
}
